            ignitionAndEngine: [ { interval: "100,000 km", timeLimit: "5 years", task: "Spark Plugs (x16)", details: "Labor intensive 16-plug service. Required for ME2.8 twin-spark logic.", parts: ["16x Bosch Plugs"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "250 EUR" }, { interval: "100,000 km", timeLimit: "N/A", task: "Valve Cover Gaskets", details: "Replace weeping gaskets and reseal breather covers.", parts: ["Elring Gaskets", "Sealant"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "150 EUR" }, { interval: "100,000 km", timeLimit: "N/A", task: "Breather Hoses", details: "Replace brittle PCV hoses to fix vacuum leaks.", parts: ["MB Genuine Hoses"], importance: "High", laborDifficulty: "Easy", estimatedCost: "80 EUR" }, { interval: "120,000 km", timeLimit: "7 years", task: "Serpentine Belt & Pulleys", details: "Replace the drive belt and idlers.", parts: ["Continental Kit"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "150 EUR" }, { interval: "150,000 km", timeLimit: "10 years", task: "Ignition Coils & Wires", details: "Inspect 16 spark plug wires for arcing.", parts: ["Bosch Wire Set"], importance: "Medium", laborDifficulty: "Intermediate", estimatedCost: "300 EUR" } ], 
