        engineeringData: { blockDesign: "90-degree 5.5L V8 Aluminum block with Silitec (Alusil) cylinder liners. Closed-deck stiffness optimization.", crankshaft: "Forged steel, 5-main bearing.", pistonSpeed: "16.2 m/s @ 6000 RPM", alternator: "Valeo 150A Water-resistant", rotatingAssembly: { pistonConstruction: "Cast aluminum, iron-coated skirts", wristPinDiameter: "22 mm", connectingRodLength: "146 mm", rodBoltSize: "M9", crankMainJournal: "64.0 mm", crankRodJournal: "52.0 mm", rodRatio: "1.66" }, cylinderHead: { combustionChamberVol: "4-valve DOHC", intakePortFlow: "Variable dual-stage magnesium manifold with tumble flaps", valveSizes: "In: 39.5mm / Ex: 30.0mm", valveStemDiameter: "6.0 mm", camshaftDuration: "Continuous sequential VVT dynamically controlled by ECU algorithms.", lifterType: "Hydraulic bucket", specialFeature: "Dynamic intake/exhaust overlap for high-RPM scavenging." }, oilAndCooling: { oilSquirters: "Piston cooling jets present", oilPumpType: "Chain-driven gear", thermostatOpening: "100°C electronically mapped", oilCooler: "Coolant-to-oil heat exchanger" }, fuelSystem: { systemType: "MPI Returnless", maxPressure: "3.8 Bar", injectors: "Solenoid 6-hole" }, tuningLimits: { maxSafeTorqueStock: "580 Nm", maxSafePowerStock: "450 hp", maxSafeRPM: "6500 RPM", weakestLink: "Timing Idler Gear, 7G-Tronic Heat Limit" }, electrical: { coils: "Individual Pencil Coils", ecu: "Bosch ME 9.7" } },
