        sisterModels: [ { name: "Mercedes-Benz E 420 (W210)", note: "The 'four-eyed' E-Class packing the exact same M119 V8 and 722.6 transmission." }, { name: "Mercedes-Benz S 500 (W140)", note: "The 5.0L big brother, utilizing the exact same M119 architecture." } ],
