        fluidCapacities: [ { system: "Engine Oil", capacity: "8.0 L", spec: "10W-40 Synthetic" }, { system: "Transmission (722.3)", capacity: "7.5 L", spec: "MB 236.14" }, { system: "Differential", capacity: "1.3 L", spec: "85W-90 GL-5" }, { system: "Coolant", capacity: "15.0 L", spec: "MB 325.0" }, { system: "Brake Fluid", capacity: "1.0 L", spec: "DOT 4 Plus" }, { system: "Power Steering", capacity: "1.0 L", spec: "MB 236.3" }, { system: "Fuel Tank", capacity: "100 L", spec: "Premium 95 RON" } ],
