            fluidsAndDrivetrain: [ { interval: "60,000 km", timeLimit: "4 yrs", task: "722.9 ATF Flush", details: "Drain ATF, drop pan, replace filter and aluminum stretch bolts. The V8 torque rapidly degrades the fluid.", parts: ["9L MB 236.14", "Filter", "Bolts"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "350 EUR" }, { interval: "100,000 km", timeLimit: "5 yrs", task: "Diff Fluid", details: "Drain and refill.", parts: ["1.2L 85W-90"], importance: "High", laborDifficulty: "Easy", estimatedCost: "80 EUR" }, { interval: "2 Years", timeLimit: "2 yrs", task: "Brake Fluid", details: "Flush DOT 4 Plus. W221 ABS is highly sensitive.", parts: ["1.0L Fluid"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "80 EUR" }, { interval: "100,000 km", timeLimit: "5 yrs", task: "Power Steering Fluid", details: "Requires clean fluid.", parts: ["MB 236.3"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "60 EUR" } ], 
            oilAndFilters: [ { interval: "10,000 km", timeLimit: "1 yr", task: "Engine Oil", details: "CRITICAL: Dirty oil accelerates the catastrophic timing gear wear.", parts: ["8.5L 5W-40", "Filter"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "120 EUR" }, { interval: "40,000 km", timeLimit: "3 yrs", task: "Air Filters", details: "Dual panel filters. Crucial for MAF health.", parts: ["2x Mann"], importance: "High", laborDifficulty: "Easy", estimatedCost: "60 EUR" }, { interval: "30,000 km", timeLimit: "2 yrs", task: "Cabin Filter", details: "Dual interior filters.", parts: ["Mahle LAK"], importance: "Low", laborDifficulty: "Easy", estimatedCost: "50 EUR" }, { interval: "80,000 km", timeLimit: "5 yrs", task: "Fuel Filter", details: "Integrated regulator style filter inside the tank.", parts: ["Knecht Filter"], importance: "Medium", laborDifficulty: "Intermediate", estimatedCost: "150 EUR" } ], 
            ignitionAndEngine: [ { interval: "100,000 km", timeLimit: "N/A", task: "Intake Manifold Check", details: "Inspect the plastic lever on the front of the intake. If broken, replace with aluminum lever.", parts: ["Aluminum Lever"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "150 EUR" }, { interval: "Every Service", timeLimit: "N/A", task: "Cam Magnet Inspection", details: "Unplug the 4 camshaft adjusters and check for oil in the connector. If oil is present, replace magnets and add isolation harnesses.", parts: ["Pierburg Magnets", "Pigtails"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "150 EUR" }, { interval: "100,000 km", timeLimit: "5 yrs", task: "Spark Plugs", details: "Replace all 8 plugs.", parts: ["8x Bosch"], importance: "High", laborDifficulty: "Easy", estimatedCost: "100 EUR" }, { interval: "120,000 km", timeLimit: "7 yrs", task: "Serpentine Belt", details: "Replace the drive belt, tensioner, and idlers.", parts: ["Conti Belt Kit"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "120 EUR" } ], 
            preventiveAndSuspension: [ { interval: "Yearly", timeLimit: "1 yr", task: "Cowl Drains Cleaning", details: "CRITICAL: Clear leaves from the windshield drains to prevent front SAM module flooding.", parts: ["Air"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "0 EUR" }, { interval: "100,000 km", timeLimit: "N/A", task: "Airmatic Check", details: "Check struts for micro-leaks. Replace compressor relay proactively.", parts: ["Hella Relay"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "20 EUR" }, { interval: "80,000 km", timeLimit: "N/A", task: "Engine Mounts", details: "Heavy V8 crushes mounts, causing severe cabin vibration.", parts: ["Lemförder"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "350 EUR" } ], 
