            engineMechanical: [ { interval: "150,000 km", timeLimit: "N/A", task: "Idle Gear & Timing Chain Inspection", details: "CRITICAL: Monitor for timing correlation fault codes (P0016/P0017) and inspect the central idle gear sprocket wear condition. Early failure requires front engine teardown.", parts: ["Timing Lock Tools", "Inspection Scope"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "250 EUR" }, { interval: "150,000 km", timeLimit: "N/A", task: "VVT Phaser Check", details: "Listen for cold start rattle indicating worn camshaft adjusters.", parts: ["None"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "0 EUR" } ] 
