        engineeringData: { blockDesign: "90-degree 4.7L V8 Aluminum block with Silitec cylinder liners. This proprietary cylinder coating is the engine's ultimate fatal flaw.", crankshaft: "Forged steel, 5-main bearing.", pistonSpeed: "15.9 m/s @ 6500 RPM", alternator: "Bosch 180A (Managed for ECO start-stop)", rotatingAssembly: { pistonConstruction: "Forged aluminum with cooling channels", wristPinDiameter: "22 mm", connectingRodLength: "146 mm", rodBoltSize: "M10", crankMainJournal: "64.0 mm", crankRodJournal: "52.0 mm", rodRatio: "1.66" }, cylinderHead: { combustionChamberVol: "4-valve DOHC", intakePortFlow: "High-velocity Direct Injection ports", valveSizes: "In: 35.0mm / Ex: 26.0mm", valveStemDiameter: "6.0 mm", camshaftDuration: "Continuous Variable Valve Timing (VVT).", lifterType: "Hydraulic bucket", specialFeature: "Liquid-to-air charge coolers and electronic wastegates." }, oilAndCooling: { oilSquirters: "High-flow dual piston cooling jets", oilPumpType: "Chain-driven variable vane pump", thermostatOpening: "100°C electronically mapped", oilCooler: "Massive external heat exchanger" }, fuelSystem: { systemType: "Bosch MED17 Direct Injection", maxPressure: "200 Bar (HPFP)", injectors: "Bosch Piezoelectric" }, tuningLimits: { maxSafeTorqueStock: "850 Nm", maxSafePowerStock: "550 hp", maxSafeRPM: "6800 RPM", weakestLink: "Silitec Cylinder Walls / Turbo Coolant Lines" }, electrical: { coils: "8x Coil-on-Plug (Multi-spark)", ecu: "Bosch MED17.7.3" } },
