            oilAndFilters: [ { interval: "8,000 km", timeLimit: "1 yr", task: "Engine Oil", details: "CRITICAL: Flawless oil maintenance is the ONLY way to delay the fatal Silitec cylinder wall scoring. Ignore factory 25k intervals.", parts: ["8.5L 5W-40", "Filter"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "140 EUR" }, { interval: "40,000 km", timeLimit: "3 yrs", task: "Air Filters", details: "Dual panel filters. Biturbo V8 demands massive airflow.", parts: ["2x Mann"], importance: "High", laborDifficulty: "Easy", estimatedCost: "70 EUR" }, { interval: "30,000 km", timeLimit: "2 yrs", task: "Cabin Filter", details: "Dual interior filters.", parts: ["Mahle LAK"], importance: "Low", laborDifficulty: "Easy", estimatedCost: "50 EUR" }, { interval: "60,000 km", timeLimit: "4 yrs", task: "Fuel Filter", details: "Integrated regulator inside the tank assembly.", parts: ["Knecht Filter"], importance: "Medium", laborDifficulty: "Intermediate", estimatedCost: "160 EUR" } ], 
            ignitionAndEngine: [ { interval: "Immediately", timeLimit: "N/A", task: "Timing Chain Tensioner & Check Valve Upgrade", details: "CRITICAL: If the engine rattles on cold start, immediately install updated check valves into the block and replace hydraulic tensioners.", parts: ["Check Valves", "Tensioners"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "600 EUR" }, { interval: "100,000 km", timeLimit: "N/A", task: "Intake Valve Walnut Blasting", details: "CRITICAL: Direct Injection causes thick carbon soot to choke intake valves. Remove manifold and blast away carbon.", parts: ["Intake Gaskets", "Walnut Shells"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "500 EUR" }, { interval: "80,000 km", timeLimit: "4 yrs", task: "Spark Plugs", details: "Replace all 8 plugs. Must use exact factory torque specs to properly 'index' the electrode.", parts: ["8x Bosch"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "140 EUR" }, { interval: "100,000 km", timeLimit: "N/A", task: "Turbo Coolant Lines", details: "Proactively replace the plastic coolant lines feeding the turbos before they shatter and overheat the engine.", parts: ["Coolant Lines"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "400 EUR" }, { interval: "Every Service", timeLimit: "N/A", task: "Cam Sensor Inspection", details: "Check cam position sensors for oil leaks into the wiring harness. Use isolation pigtails.", parts: ["Isolation Wires"], importance: "High", laborDifficulty: "Easy", estimatedCost: "50 EUR" } ], 
            preventiveAndSuspension: [ { interval: "Yearly", timeLimit: "1 yr", task: "Cowl Drains Cleaning", details: "CRITICAL: Clear leaves from windshield drains to prevent front SAM module flooding.", parts: ["Air"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "0 EUR" }, { interval: "100,000 km", timeLimit: "N/A", task: "Airmatic Check", details: "Check struts for micro-leaks. Replace compressor relay proactively.", parts: ["Hella Relay"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "20 EUR" }, { interval: "80,000 km", timeLimit: "N/A", task: "Engine Mounts", details: "700 Nm of torque literally tears fluid-filled mounts apart, causing severe vibration.", parts: ["Lemförder"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "400 EUR" } ], 
