        torqueSpecs: [ { part: "Oil Drain Plug", value: "30 Nm", note: "Replace copper washer." }, { part: "Spark Plugs (x8)", value: "23 Nm", note: "CRITICAL: Must be indexed perfectly." }, { part: "Timing Tensioner Bolts", value: "14 Nm", note: "Tighten evenly." }, { part: "Transfer Case Drain", value: "30 Nm", note: "Use new sealing ring." }, { part: "High Pressure Fuel Pump", value: "12 Nm", note: "Tighten crosswise." }, { part: "Turbo Coolant Banjo Bolts", value: "20 Nm", note: "Replace crush washers." }, { part: "Transmission Pan", value: "4 Nm + 180°", note: "Stretch bolts." }, { part: "Wheel Bolts", value: "150 Nm", note: "Critical for heavy W221 chassis." }, { part: "Camshaft Sensors", value: "8 Nm", note: "Replace O-rings." }, { part: "Ignition Coils", value: "9 Nm", note: "Do not overtighten." } ],
        engineeringData: { blockDesign: "90-degree 4.7L V8 Aluminum block with Silitec cylinder liners. Features a modified oil pan to accommodate the 4MATIC front drive shafts. The proprietary cylinder coating is the engine's ultimate fatal flaw.", crankshaft: "Forged steel, 5-main bearing.", pistonSpeed: "15.9 m/s @ 6500 RPM", alternator: "Bosch 180A (Managed for ECO start-stop)", rotatingAssembly: { pistonConstruction: "Forged aluminum with cooling channels", wristPinDiameter: "22 mm", connectingRodLength: "146 mm", rodBoltSize: "M10", crankMainJournal: "64.0 mm", crankRodJournal: "52.0 mm", rodRatio: "1.66" }, cylinderHead: { combustionChamberVol: "4-valve DOHC", intakePortFlow: "High-velocity Direct Injection ports", valveSizes: "In: 35.0mm / Ex: 26.0mm", valveStemDiameter: "6.0 mm", camshaftDuration: "Continuous Variable Valve Timing (VVT).", lifterType: "Hydraulic bucket", specialFeature: "Liquid-to-air charge coolers and electronic wastegates." }, oilAndCooling: { oilSquirters: "High-flow dual piston cooling jets", oilPumpType: "Chain-driven variable vane pump", thermostatOpening: "100°C electronically mapped", oilCooler: "Massive external heat exchanger" }, fuelSystem: { systemType: "Bosch MED17 Direct Injection", maxPressure: "200 Bar (HPFP)", injectors: "Bosch Piezoelectric" }, tuningLimits: { maxSafeTorqueStock: "750 Nm", maxSafePowerStock: "500 hp", maxSafeRPM: "6800 RPM", weakestLink: "Silitec Cylinder Walls / 4MATIC Transfer Case Chain" }, electrical: { coils: "8x Coil-on-Plug (Multi-spark)", ecu: "Bosch MED17.7.3 with 4ETS Integration" } },
