            preventiveAndSuspension: [ { interval: "Yearly", timeLimit: "1 yr", task: "Cowl Drains Cleaning", details: "CRITICAL: Clear leaves from windshield drains to prevent front SAM module flooding.", parts: ["Air"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "0 EUR" }, { interval: "100,000 km", timeLimit: "N/A", task: "Airmatic Check", details: "Check struts for micro-leaks. Replace compressor relay proactively.", parts: ["Hella Relay"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "20 EUR" }, { interval: "80,000 km", timeLimit: "N/A", task: "Engine Mounts", details: "700 Nm of torque literally tears fluid-filled mounts apart. 4MATIC axles make this a nightmare.", parts: ["Lemförder"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "550 EUR" } ], 
