            preventiveAndSuspension: [ { interval: "Yearly", timeLimit: "1 yr", task: "Cowl Drains Cleaning", details: "CRITICAL: Clear leaves from windshield drains to prevent front SAM module flooding.", parts: ["Air"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "0 EUR" }, { interval: "100,000 km", timeLimit: "N/A", task: "Airmatic Check", details: "Check struts for micro-leaks. Replace compressor relay proactively.", parts: ["Hella Relay"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "20 EUR" }, { interval: "80,000 km", timeLimit: "N/A", task: "Engine Mounts", details: "The 4-cylinder engine inherently vibrates more than a V6. Mounts fail frequently.", parts: ["Lemförder"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "300 EUR" }, { interval: "Every Service", timeLimit: "N/A", task: "DPF Ash Load Check", details: "Use STAR diagnosis to check DPF fill level and trigger forced regeneration if needed.", parts: ["Diagnostics"], importance: "High", laborDifficulty: "Easy", estimatedCost: "50 EUR" }, { interval: "100,000 km", timeLimit: "N/A", task: "DPF Pressure Sensor", details: "Proactively replace to ensure proper DPF regeneration cycles.", parts: ["Bosch Sensor"], importance: "High", laborDifficulty: "Easy", estimatedCost: "60 EUR" } ], 
