            oilAndFilters: [ { interval: "10,000 km", timeLimit: "1 yr", task: "Engine Oil", details: "CRITICAL: Must use Low-SAPS 229.51 oil to prevent DPF clogging. Check turbo inlet seal during change.", parts: ["8.5L 5W-30 Low-SAPS", "Filter"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "130 EUR" }, { interval: "10,000 km", timeLimit: "1 yr", task: "Turbo Inlet Seal", details: "CRITICAL: Replace the orange turbo intake seal at EVERY oil change to stop oil dripping onto the M55 motor.", parts: ["MB Red Seal"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "25 EUR" }, { interval: "40,000 km", timeLimit: "2 yrs", task: "Fuel Filter", details: "Protects high-pressure pump and delicate Piezo injectors.", parts: ["Knecht Filter"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "60 EUR" }, { interval: "40,000 km", timeLimit: "3 yrs", task: "Air Filters", details: "Dual panel filters. V6 sucks massive air.", parts: ["2x Mann"], importance: "High", laborDifficulty: "Easy", estimatedCost: "60 EUR" } ], 
            ignitionAndEngine: [ { interval: "150,000 km", timeLimit: "N/A", task: "Oil Cooler Seals", details: "Proactive replacement of the oil cooler seals in the engine V before they hemorrhage oil. Massive labor job.", parts: ["Viton Seals", "Gaskets"], importance: "Critical", laborDifficulty: "Extreme", estimatedCost: "1200 EUR" }, { interval: "150,000 km", timeLimit: "N/A", task: "Exhaust Manifold Inspection", details: "Remove turbo and inspect manifolds for internal flaking. Replace if crumbling to save the turbo.", parts: ["Manifolds"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "800 EUR" }, { interval: "150,000 km", timeLimit: "N/A", task: "Glow Plugs & Module", details: "Spray penetrating oil prior. Do not exceed 20Nm torque. Replace Beru controller module.", parts: ["6x Beru Plugs", "Module"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "250 EUR" }, { interval: "120,000 km", timeLimit: "7 yrs", task: "Serpentine Belt", details: "Replace drive belt and idlers.", parts: ["Conti Belt Kit"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "120 EUR" } ], 
            preventiveAndSuspension: [ { interval: "Yearly", timeLimit: "1 yr", task: "Cowl Drains Cleaning", details: "CRITICAL: Clear leaves from windshield drains to prevent front SAM module flooding.", parts: ["Air"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "0 EUR" }, { interval: "100,000 km", timeLimit: "N/A", task: "Airmatic Check", details: "Check struts for micro-leaks. Replace compressor relay proactively.", parts: ["Hella Relay"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "20 EUR" }, { interval: "80,000 km", timeLimit: "N/A", task: "Engine Mounts", details: "Heavy diesel torque crushes mounts, causing severe cabin vibration.", parts: ["Lemförder"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "350 EUR" }, { interval: "Every Service", timeLimit: "N/A", task: "DPF Ash Load Check", details: "Use STAR diagnosis to check DPF fill level.", parts: ["Diagnostics"], importance: "High", laborDifficulty: "Easy", estimatedCost: "50 EUR" } ], 
            coolingAndHvac: [ { interval: "100,000 km", timeLimit: "5 yrs", task: "Coolant Flush", details: "Protect aluminum block.", parts: ["10.0L MB 325.0"], importance: "High", laborDifficulty: "Easy", estimatedCost: "100 EUR" }, { interval: "150,000 km", timeLimit: "N/A", task: "Thermostat Replacement", details: "Diesels run cold if thermostat fails open, ruining MPG and DPF regens.", parts: ["Wahler"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "120 EUR" } ], 
