        engineeringData: { blockDesign: "72-degree 3.0L V6 Aluminum block with cast iron liners. Extremely cramped engine valley houses turbo, oil cooler, and M55 motor. Modified oil pan for 4MATIC front axles.", crankshaft: "Forged steel, 4-main bearing.", pistonSpeed: "13.6 m/s @ 4500 RPM", alternator: "Bosch 180A", rotatingAssembly: { pistonConstruction: "Cast aluminum with internal cooling", wristPinDiameter: "30 mm", connectingRodLength: "149 mm", rodBoltSize: "M10", crankMainJournal: "64.0 mm", crankRodJournal: "52.0 mm", rodRatio: "1.68" }, cylinderHead: { combustionChamberVol: "4-valve DOHC", intakePortFlow: "Variable dual intakes with active swirl flaps", valveSizes: "In: 28.0mm / Ex: 26.0mm", valveStemDiameter: "6.0 mm", camshaftDuration: "Diesel-optimized.", lifterType: "Hydraulic bucket", specialFeature: "Piezoelectric injectors." }, oilAndCooling: { oilSquirters: "High-flow jets", oilPumpType: "Chain-driven gear", thermostatOpening: "87°C mechanical", oilCooler: "Block-V mounted heat exchanger" }, fuelSystem: { systemType: "Bosch EDC16", maxPressure: "1600 Bar", injectors: "Bosch Piezoelectric" }, tuningLimits: { maxSafeTorqueStock: "650 Nm", maxSafePowerStock: "300 hp", maxSafeRPM: "4800 RPM", weakestLink: "Exhaust Manifolds / M55 Motor / Transfer Case" }, electrical: { coils: "N/A", ecu: "Bosch EDC16CP31" } },
