        engineeringData: { blockDesign: "75-degree 4.0L V8 Aluminum block with cast iron cylinder liners. The unusual 75-degree V-angle was chosen to fit the massive engine into tight engine bays, but it compromises natural balance, necessitating a complex balance shaft system.", crankshaft: "Forged steel, 5-main bearing.", pistonSpeed: "14.5 m/s @ 4500 RPM", alternator: "Bosch 180A Water-Cooled", rotatingAssembly: { pistonConstruction: "Cast aluminum with internal oil cooling", wristPinDiameter: "30 mm", connectingRodLength: "149 mm", rodBoltSize: "M10", crankMainJournal: "64.0 mm", crankRodJournal: "52.0 mm", rodRatio: "1.68" }, cylinderHead: { combustionChamberVol: "4-valve DOHC", intakePortFlow: "High-velocity naturally swirling ports", valveSizes: "In: 28.0mm / Ex: 26.0mm", valveStemDiameter: "6.0 mm", camshaftDuration: "Diesel-optimized fixed profiles.", lifterType: "Hydraulic bucket", specialFeature: "Master/Slave ECU control for precise V8 bank synchronization." }, oilAndCooling: { oilSquirters: "High-flow dual piston cooling jets", oilPumpType: "Chain-driven high-capacity gear", thermostatOpening: "87°C mechanical", oilCooler: "Massive block-mounted heat exchanger" }, fuelSystem: { systemType: "Dual Bosch EDC16 Common Rail", maxPressure: "1600 Bar", injectors: "Bosch Piezoelectric" }, tuningLimits: { maxSafeTorqueStock: "800 Nm", maxSafePowerStock: "360 hp", maxSafeRPM: "4800 RPM", weakestLink: "722.9 Transmission Clutches / Timing Chain" }, electrical: { coils: "N/A", ecu: "Dual Bosch EDC16CP31" } },
