            fluidsAndDrivetrain: [ { interval: "60,000 km", timeLimit: "4 yrs", task: "ATF Flush", details: "Drain ATF, drop pan, replace filter. MUST use correct MB fluid spec depending on 7G or 9G transmission.", parts: ["9L ATF", "Filter", "Bolts"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "380 EUR" }, { interval: "60,000 km", timeLimit: "4 yrs", task: "Transfer Case Fluid", details: "Drain and refill the 4MATIC transfer case to prevent internal bearing failure.", parts: ["0.5L MB 236.12"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "80 EUR" }, { interval: "100,000 km", timeLimit: "5 yrs", task: "Diff Fluid (Front/Rear)", details: "Drain and refill both differentials.", parts: ["2.3L 85W-90"], importance: "High", laborDifficulty: "Easy", estimatedCost: "120 EUR" }, { interval: "2 Years", timeLimit: "2 yrs", task: "Brake Fluid", details: "Flush DOT 4 Plus.", parts: ["1.0L Fluid"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "80 EUR" }, { interval: "Every Service", timeLimit: "1 yr", task: "AdBlue Refill", details: "Fill the SCR tank with high-quality ISO 22241-1 DEF to prevent system lockouts.", parts: ["25L AdBlue"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "30 EUR" } ], 
            oilAndFilters: [ { interval: "10,000 km", timeLimit: "1 yr", task: "Engine Oil", details: "CRITICAL: Must use Low-SAPS 229.52 oil to prevent DPF clogging. Check turbo inlet seal during change.", parts: ["8.5L 5W-30 Low-SAPS", "Filter"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "140 EUR" }, { interval: "10,000 km", timeLimit: "1 yr", task: "Turbo Inlet Seal", details: "CRITICAL: Replace the orange turbo intake seal at EVERY oil change to stop oil dripping onto the M55 motor.", parts: ["MB Red Seal"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "25 EUR" }, { interval: "40,000 km", timeLimit: "2 yrs", task: "Fuel Filter", details: "Protects the 1800-bar high-pressure pump and delicate Piezo injectors.", parts: ["Knecht Filter"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "70 EUR" }, { interval: "40,000 km", timeLimit: "3 yrs", task: "Air Filters", details: "Dual panel filters. V6 sucks massive air.", parts: ["2x Mann"], importance: "High", laborDifficulty: "Easy", estimatedCost: "60 EUR" } ], 
            ignitionAndEngine: [ { interval: "150,000 km", timeLimit: "N/A", task: "Oil Cooler Seals", details: "Proactive replacement of the oil cooler seals in the engine V before they hemorrhage oil. Massive labor job.", parts: ["Viton Seals", "Gaskets"], importance: "Critical", laborDifficulty: "Extreme", estimatedCost: "1200 EUR" }, { interval: "150,000 km", timeLimit: "N/A", task: "Exhaust Manifold Inspection", details: "Remove turbo and inspect manifolds for internal flaking. Replace if crumbling to save the turbo.", parts: ["Manifolds"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "800 EUR" }, { interval: "150,000 km", timeLimit: "N/A", task: "Glow Plugs & Module", details: "Spray penetrating oil prior. Do not exceed 20Nm torque. Replace Beru controller module.", parts: ["6x Beru Plugs", "Module"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "250 EUR" }, { interval: "120,000 km", timeLimit: "7 yrs", task: "Serpentine Belt", details: "Replace drive belt and idlers.", parts: ["Conti Belt Kit"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "120 EUR" } ], 
            preventiveAndSuspension: [ { interval: "Yearly", timeLimit: "1 yr", task: "Cowl Drains Cleaning", details: "CRITICAL: Clear leaves from windshield drains to prevent front SAM module flooding.", parts: ["Air"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "0 EUR" }, { interval: "100,000 km", timeLimit: "N/A", task: "Airmatic Check", details: "Check struts for micro-leaks. Replace compressor relay proactively.", parts: ["Hella Relay"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "20 EUR" }, { interval: "80,000 km", timeLimit: "N/A", task: "Engine Mounts", details: "Heavy diesel torque crushes mounts. 4MATIC axles make this a nightmare of a job.", parts: ["Lemförder"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "550 EUR" }, { interval: "Every Service", timeLimit: "N/A", task: "SCR & DPF Check", details: "Use STAR diagnosis to check DPF fill level and AdBlue heater status.", parts: ["Diagnostics"], importance: "High", laborDifficulty: "Easy", estimatedCost: "50 EUR" } ], 
